class Shape { accept(v) { return v.visit(this); } }
class Rect extends Shape {
  constructor(w, h) { super(); this.w = w; this.h = h; }
}
class AreaV { visit(r) { return r.w * r.h; } }
console.log(new Rect(3, 4).accept(new AreaV()));
